"""A Model context generated by the first legacy cutover is repaired once proven.

The first v2 cutover planned without an official directory, so a legacy row
that omitted its context minted its Model at the 128,000 import default
(``anthropic/claude-opus-5`` on the owner instance). World sync replaces
exactly that value with the developer fact (exact identity, else the unique
same-creator spelling-key match), and only when replaying the redacted
cutover receipt proves no legacy row declared it. Declared limits, other
values, evidence-backed registrations and recovery receipts stay untouched.
"""
import pytest

from lib.model_routing import (
    InMemoryModelRoutingRepository, OwnerBoundary, execute_migration, plan_legacy_migration)
from lib.model_routing import world_catalog
from lib.model_routing.metadata_migration import (
    cutover_generated_model_contexts, reconcile_generated_model_context)

pytestmark = pytest.mark.unit

IMPORT_DEFAULT = 128_000


def _legacy(*seeds):
    return {'providers': [{'id': 'relay', 'base_url': 'https://relay.invalid/v1',
                           'api_keys': ['placeholder'], 'models': list(seeds)}]}


def _official(model_id, window):
    return {'creator_id': 'anthropic', 'model_id': model_id, 'display_name': model_id,
            'capabilities': ['text', 'thinking', 'vision'], 'context_window': window,
            'quality_rank': 50.0}


@pytest.fixture
def cutover(monkeypatch):
    """Install an owner authority through a first, directory-less cutover."""
    def install(*seeds, directory):
        repository, owner = InMemoryModelRoutingRepository(), OwnerBoundary.create(4242)
        assert execute_migration(repository, owner, plan_legacy_migration(_legacy(*seeds))).enabled
        monkeypatch.setattr(world_catalog, '_world_catalog_rows', lambda templates: ([], []))
        monkeypatch.setattr(world_catalog, '_retired_model_keys', lambda templates: set())
        monkeypatch.setattr(world_catalog, '_official_directory', lambda templates: directory)
        return repository, owner
    return install


def _model(document, model_id):
    return next(row for row in document['models'] if row['model_id'] == model_id)


@pytest.mark.parametrize('model_id,official_id', [
    ('claude-test-6', 'claude-test-6'), ('claude-test-6.5', 'claude-test-6-5')])
def test_cutover_default_takes_the_official_fact_and_inheriting_supply_follows(
        cutover, model_id, official_id):
    repository, owner = cutover({'model_id': model_id, 'capabilities': ['text', 'thinking']},
                                directory=[_official(official_id, 1_000_000)])
    before = repository.get(owner).document
    assert _model(before, model_id)['context_window'] == IMPORT_DEFAULT
    summary = world_catalog.sync_world_model_catalog(boundary=owner, repository=repository)
    assert summary['model_contexts_repaired'] == 1
    after = repository.get(owner)
    assert _model(after.document, model_id)['context_window'] == 1_000_000
    offering, = after.document['offerings']
    assert offering['inherited_model_fields'] == ['context_window']
    assert offering['context_window'] == 1_000_000
    again = world_catalog.sync_world_model_catalog(boundary=owner, repository=repository)
    assert again['revision'] == after.revision


def test_declared_limit_owner_value_and_registration_evidence_are_preserved(cutover):
    repository, owner = cutover(
        {'model_id': 'claude-test-6', 'context_window': IMPORT_DEFAULT},
        {'model_id': 'claude-test-7'}, {'model_id': 'claude-test-8'},
        directory=[_official(name, 1_000_000)
                   for name in ('claude-test-6', 'claude-test-7', 'claude-test-8')])
    current = repository.get(owner)
    document = current.document
    _model(document, 'claude-test-7')['context_window'] = 200_000
    _model(document, 'claude-test-8')['registration_metadata'] = {
        'release_date': '2026-08', 'checked_at': '2026-10-23',
        'source_urls': ['https://docs.example.invalid/models']}
    repository.compare_and_swap(owner, document, expected_revision=current.revision)
    summary = world_catalog.sync_world_model_catalog(boundary=owner, repository=repository)
    assert summary['model_contexts_repaired'] == 0
    models = {row['model_id']: row['context_window'] for row in repository.get(owner).document['models']}
    assert models == {'claude-test-6': IMPORT_DEFAULT, 'claude-test-7': 200_000,
                      'claude-test-8': IMPORT_DEFAULT}
    again = world_catalog.sync_world_model_catalog(boundary=owner, repository=repository)
    assert again['revision'] == summary['revision']


def test_repair_is_evaluated_once_and_a_later_owner_value_is_kept(cutover, monkeypatch):
    repository, owner = cutover({'model_id': 'claude-test-6'},
                                directory=[_official('claude-test-6', 1_000_000)])
    first = world_catalog.sync_world_model_catalog(boundary=owner, repository=repository)
    assert first['model_contexts_repaired'] == 1
    current = repository.get(owner)
    migration = current.document['migration']
    assert migration['context_repair_receipt_id'] == migration['receipt_id']
    # The owner deliberately narrows the Model back to the old value.
    document = current.document
    _model(document, 'claude-test-6')['context_window'] = IMPORT_DEFAULT
    edited = repository.compare_and_swap(owner, document, expected_revision=current.revision)
    monkeypatch.setattr(repository, 'migration_receipt', lambda *_a: pytest.fail(
        'an evaluated cutover receipt is never replayed again'))
    again = world_catalog.sync_world_model_catalog(boundary=owner, repository=repository)
    assert again['revision'] == edited.revision
    assert _model(repository.get(owner).document, 'claude-test-6')['context_window'] == (
        IMPORT_DEFAULT)


def test_one_sync_reads_one_template_snapshot(monkeypatch):
    from lib.provider import provider_template_recipes
    repository, owner = InMemoryModelRoutingRepository(), OwnerBoundary.create(4242)
    plan = plan_legacy_migration(_legacy({'model_id': 'claude-test-6'}))
    assert execute_migration(repository, owner, plan).enabled
    snapshot, loads, seen = [], [], {}
    monkeypatch.setattr(provider_template_recipes, 'load_provider_templates',
                        lambda: loads.append(1) or snapshot)
    # The real steps run (the cutover proof includes the directory step); a
    # spy records the template snapshot each step is given.
    steps = ('_world_catalog_rows', '_retired_model_keys', '_official_directory')
    for step in steps:
        real = getattr(world_catalog, step)
        monkeypatch.setattr(world_catalog, step, lambda templates, step=step, real=real: (
            seen.setdefault(step, templates), real(templates))[1])
    world_catalog.sync_world_model_catalog(boundary=owner, repository=repository)
    assert len(loads) == 1
    assert set(seen) == set(steps)
    assert all(templates is snapshot for templates in seen.values())


def test_marker_is_recorded_even_when_nothing_needs_repair(cutover):
    repository, owner = cutover({'model_id': 'claude-test-6', 'context_window': 200_000},
                                directory=[_official('claude-test-6', 1_000_000)])
    summary = world_catalog.sync_world_model_catalog(boundary=owner, repository=repository)
    assert summary['model_contexts_repaired'] == 0
    migration = repository.get(owner).document['migration']
    assert migration['context_repair_receipt_id'] == migration['receipt_id']


def _receipt(plan, document, **overrides):
    receipt = {'receipt_id': document['migration']['receipt_id'], 'status': 'committed',
               'from_revision': 0, 'redacted_backup': plan.redacted_backup}
    receipt.update(overrides)
    return {'receipt': receipt}


@pytest.mark.parametrize('overrides', [
    {'from_revision': 3}, {'status': 'failed'}, {'receipt_id': 'migration_other'},
    {'redacted_backup': {}}], ids=['recovery', 'not-committed', 'other-cutover', 'no-backup'])
def test_only_the_active_first_cutover_receipt_proves_a_generated_default(overrides):
    plan = plan_legacy_migration(_legacy({'model_id': 'claude-test-6'}))
    document = plan.document
    document['migration'] = {'source': 'legacy_provider_configuration', 'migrated_at': 1.0,
                             'receipt_id': 'migration_cutover'}
    assert cutover_generated_model_contexts(document, _receipt(plan, document)) == {
        ('anthropic', 'claude-test-6')}
    assert cutover_generated_model_contexts(document, _receipt(plan, document, **overrides)) == set()


@pytest.mark.parametrize('directory', [
    [_official('claude-test-6.0', IMPORT_DEFAULT)],
    [_official('claude-test-6-0', 1_000_000), _official('claude_test_6_0', 900_000)],
    [_official('claude-test-6-0-20270101', 1_000_000)],
    [],
], ids=['official-equals-default', 'ambiguous-respelling', 'dated-snapshot', 'unknown'])
def test_without_one_differing_official_fact_the_generated_value_stays(directory):
    document = plan_legacy_migration(_legacy({'model_id': 'claude-test-6.0'})).document
    assert reconcile_generated_model_context(
        document, generated={('anthropic', 'claude-test-6.0')}, official_directory=directory) == []
    assert _model(document, 'claude-test-6.0')['context_window'] == IMPORT_DEFAULT
